_CORE_SRC = '# Exact action format: {"moves": [[from_node, to_node, count], ...]}.\n# Payout: "if player_units[i] > opponent_units[i]: you earn demand[i]";\n# a strict opponent majority earns the opponent demand, and ties earn nobody.\n# Cost: "MOVE_COST = 0.5" for every unit moved by a legal move.\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 80\nMOVE_COST = 0.5\n\n\ndef payout(own, opponent, demand):\n    """Exact revenue for the player, not a capacity-share approximation."""\n    return demand if own > opponent else 0\n\n\ndef margin(own, opponent, demand):\n    return payout(own, opponent, demand) - payout(opponent, own, demand)\n\n\ndef preprocess_map(obs):\n    n = int(obs["n_nodes"])\n    adj = [[] for _ in range(n)]\n    capacities = {}\n    for edge, capacity in zip(obs["edges"], obs["edge_capacity"]):\n        u, v = map(int, edge)\n        adj[u].append(v)\n        adj[v].append(u)\n        capacities[min(u, v), max(u, v)] = int(capacity)\n    for row in adj:\n        row.sort()\n    distances = []\n    for source in range(n):\n        dist = [n + 1] * n\n        dist[source] = 0\n        queue = deque([source])\n        while queue:\n            u = queue.popleft()\n            for v in adj[u]:\n                if dist[v] > dist[u] + 1:\n                    dist[v] = dist[u] + 1\n                    queue.append(v)\n        distances.append(dist)\n    hops = [[-1] * n for _ in range(n)]\n    for u in range(n):\n        for target in range(n):\n            if u != target:\n                choices = [v for v in adj[u]\n                           if distances[v][target] == distances[u][target] - 1]\n                if choices:\n                    hops[u][target] = min(\n                        choices,\n                        key=lambda v: (\n                            -capacities[min(u, v), max(u, v)], v\n                        ),\n                    )\n    return n, adj, capacities, distances, hops\n\n\ndef legal_action(have, want, map_data):\n    """Closest-first transport, validated against original units and shared edges."""\n    n, adj, capacities, distances, hops = map_data\n    surplus = [max(0, have[v] - want[v]) for v in range(n)]\n    deficit = [max(0, want[v] - have[v]) for v in range(n)]\n    available = list(have)\n    remaining_capacity = dict(capacities)\n    pairs = sorted(\n        (distances[s][t], s, t)\n        for s in range(n) if surplus[s]\n        for t in range(n) if deficit[t]\n    )\n    orders = {}\n    for _, source, target in pairs:\n        hop = hops[source][target]\n        if hop < 0:\n            continue\n        edge = (min(source, hop), max(source, hop))\n        count = min(surplus[source], deficit[target],\n                    available[source], remaining_capacity.get(edge, 0))\n        if count <= 0:\n            continue\n        surplus[source] -= count\n        deficit[target] -= count\n        available[source] -= count\n        remaining_capacity[edge] -= count\n        orders[source, hop] = orders.get((source, hop), 0) + count\n\n    # Independently replay the aggregated orders, never allowing arrivals to move.\n    available = list(have)\n    remaining_capacity = dict(capacities)\n    moves = []\n    for (source, target), count in sorted(orders.items()):\n        edge = (min(source, target), max(source, target))\n        count = min(int(count), available[source],\n                    remaining_capacity.get(edge, 0))\n        if source != target and target in adj[source] and count > 0:\n            moves.append([int(source), int(target), int(count)])\n            available[source] -= count\n            remaining_capacity[edge] -= count\n    return {"moves": moves}\n\n\ndef allocation_candidate(have, opponent, demand, map_data, horizon, travel_weight):\n    """Threshold-aware marginal allocation, implemented as a tiny exact knapsack.\n\n    Kappa\'s strict-majority payoff is NOT concave: the first unit of a\n    multi-unit takeover can have zero marginal value. Considering whole threshold\n    bundles avoids the zero-marginal trap of a literal one-unit heap allocator.\n    """\n    n, _, _, distances, _ = map_data\n    total = sum(have)\n    values = []\n    for target in range(n):\n        trips = sorted(\n            distances[source][target]\n            for source in range(n)\n            for _ in range(have[source])\n        )\n        cumulative = [0]\n        for length in trips:\n            cumulative.append(cumulative[-1] + length)\n        row = []\n        baseline = margin(0, opponent[target], demand[target])\n        for count in range(total + 1):\n            improvement = margin(count, opponent[target], demand[target]) - baseline\n            # Winning/tie bundles only pay once enough units have arrived.\n            threshold = opponent[target] + (count > opponent[target])\n            delay = trips[min(count, max(1, threshold)) - 1] if count else 0\n            productive = max(0, horizon - max(0, delay - 1))\n            travel = MOVE_COST * cumulative[count]\n            # Small target-change penalty creates deterministic hysteresis.\n            churn = 0.12 * abs(count - have[target])\n            row.append(productive * improvement\n                       - travel_weight * travel - churn)\n        values.append(row)\n\n    dp = [-1e100] * (total + 1)\n    dp[0] = 0.0\n    parents = []\n    for row in values:\n        nxt = [-1e100] * (total + 1)\n        parent = [0] * (total + 1)\n        for used in range(total + 1):\n            if dp[used] < -1e90:\n                continue\n            for count in range(total - used + 1):\n                value = dp[used] + row[count]\n                if value > nxt[used + count] + 1e-9:\n                    nxt[used + count] = value\n                    parent[used + count] = count\n        parents.append(parent)\n        dp = nxt\n    target = [0] * n\n    used = total\n    for node in range(n - 1, -1, -1):\n        target[node] = parents[node][used]\n        used -= target[node]\n    return target\n\n\ndef evaluate_plan(have, opponent, demand, target, map_data, horizon, deadline):\n    """Replay capacity-limited travel and exact payouts against a stationary enemy."""\n    position = list(have)\n    score = 0.0\n    first_action = legal_action(position, target, map_data)\n    movement = 0\n    for step in range(horizon):\n        if time.perf_counter() >= deadline:\n            return None, first_action\n        action = first_action if step == 0 else legal_action(position, target, map_data)\n        for source, destination, count in action["moves"]:\n            position[source] -= count\n            position[destination] += count\n            score -= MOVE_COST * count\n            movement += count\n        revenue = sum(margin(position[v], opponent[v], demand[v])\n                      for v in range(len(position)))\n        score += revenue\n        if not action["moves"]:\n            score += (horizon - step - 1) * revenue\n            break\n    return score - 0.08 * movement, first_action\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n        self.target = None\n        self.bad_reports = 0\n        self.conservative = False\n\n    def act(self, obs):\n        started = time.perf_counter()\n        deadline = started + max(0.0, 0.58 * TIME_BUDGET)\n        if self.map_data is None:\n            self.map_data = preprocess_map(obs)\n        have = list(obs["player_units"])\n        opponent = list(obs["opponent_units"])\n        demand = list(obs["demand"])\n        if (obs.get("n_invalid_actions_last_turn", 0) or\n                not obs.get("action_format_correct_last_turn", True)):\n            self.bad_reports += 1\n        if self.bad_reports >= 2:\n            self.conservative = True\n        left = max(0, N_TURNS - int(obs.get("turn", 0)))\n        if left == 0 or not sum(have):\n            return {"moves": []}\n\n        horizon = min(left, 14)\n        best_target = list(have)\n        best_action = {"moves": []}\n        best_score = horizon * sum(\n            margin(have[v], opponent[v], demand[v]) for v in range(len(have))\n        )\n\n        candidates = []\n        if self.target is not None and sum(self.target) == sum(have):\n            candidates.append(self.target)\n        # The larger travel weight offers a cautious alternative near congestion.\n        weights = (1.0,) if self.conservative else (1.0, 2.5, 0.55)\n        for weight in weights:\n            if time.perf_counter() >= deadline:\n                break\n            candidates.append(allocation_candidate(\n                have, opponent, demand, self.map_data, horizon, weight\n            ))\n        for target in candidates:\n            if time.perf_counter() >= deadline:\n                break\n            score, action = evaluate_plan(\n                have, opponent, demand, target, self.map_data, horizon, deadline\n            )\n            if score is not None and score > best_score + 0.35:\n                best_score = score\n                best_target = list(target)\n                best_action = action\n\n        self.target = best_target\n        # Rebuild from the start-of-turn counts for final legality validation.\n        if best_action["moves"]:\n            return legal_action(have, best_target, self.map_data)\n        return {"moves": []}\n'
_CORE_CLASS = 'Strategy'
_FALLBACK_SRC = None
_FALLBACK_CLASS = 'Strategy'
_ACT_LIMIT_S = 0.7
_CORE_SHARE = 0.75
_TIME_BUDGET = 0.25
_IMPORT_LIMIT_S = 4.5
_FALLBACK_IMPORT_LIMIT_S = 1.5
_CORE_INIT_LIMIT_S = 2.5
_FALLBACK_INIT_LIMIT_S = 1.5
_MAX_REPLY_CHARS = 900000

_MIN_FALLBACK_S = 0.05
_REPEAT_S = 0.05  # after the first alarm, re-fire every 50 ms until the call returns
_STATE = {"armed": False}
_GUARD_CODES = set()


class _GuardTimeout(BaseException):
    """Raised by the guard's timer. A BaseException: `except Exception` cannot swallow it."""


class _Sink:
    """Swallows output: strategy code must not flood the worker's stderr."""

    encoding = "utf-8"
    errors = "replace"

    def write(self, s):
        return len(s)

    def writelines(self, lines):
        return None

    def flush(self):
        return None

    def isatty(self):
        return False


_SINK = _Sink()


def _noop_print(*args, **kwargs):
    return None


def _on_alarm(signum, frame):
    if _STATE["armed"] and (frame is None or frame.f_code not in _GUARD_CODES):
        raise _GuardTimeout()


def _can_time():
    return (
        hasattr(_signal, "setitimer")
        and hasattr(_signal, "SIGALRM")
        and _threading.current_thread() is _threading.main_thread()
    )


def _plain(value):
    """(True, plain copy) if value is a literal within the reply limit, else (False, None)."""
    try:
        text = repr(value)
        if len(text) > _MAX_REPLY_CHARS:
            return False, None
        if not text.isascii() and len(text.encode("utf-8", "replace")) > _MAX_REPLY_CHARS:
            return False, None  # arena's reply limit counts bytes
        copy = _ast.literal_eval(text)
        if not bool(copy == value):  # NaN, or a type whose repr is not its value
            return False, None
        return True, copy
    except Exception:
        return False, None


def _call(fn, args, limit, check):
    """fn(*args) under a hard timer: (status, value, error, secs). Never raises.

    status: 'ok', 'timeout', 'exception' or 'bad' (check=True and not a plain literal).
    """
    status = "exception"
    value = None
    error = None
    timed = False
    prev_handler = None
    prev_timer = (0.0, 0.0)
    out, err, inp = _sys.stdout, _sys.stderr, _sys.stdin
    t0 = _time.perf_counter()
    try:
        if limit > 0 and _can_time():
            prev_handler = _signal.signal(_signal.SIGALRM, _on_alarm)
            prev_timer = _signal.setitimer(_signal.ITIMER_REAL, limit, _REPEAT_S)
            timed = True
        _sys.stdout = _sys.stderr = _SINK
        _sys.stdin = None  # arena's protocol pipe: untrusted code must not read it
        _STATE["armed"] = timed
        try:
            result = fn(*args)
            if check:
                ok, result = _plain(result)
                status = "ok" if ok else "bad"
            else:
                status = "ok"
            value = result
        except _GuardTimeout as e:
            status = "timeout"
            error = e
        except BaseException as e:
            status = "exception"
            error = e
    except BaseException as e:
        if status == "exception" and error is None:
            error = e
    finally:
        _STATE["armed"] = False
        if timed:
            try:
                _signal.setitimer(_signal.ITIMER_REAL, 0.0)
                _signal.signal(
                    _signal.SIGALRM, prev_handler if prev_handler is not None else _signal.SIG_DFL
                )
                if prev_timer[0] > 0:
                    spent = _time.perf_counter() - t0
                    _signal.setitimer(
                        _signal.ITIMER_REAL, max(prev_timer[0] - spent, 1e-4), prev_timer[1]
                    )
            except BaseException:
                pass
        _sys.stdout, _sys.stderr, _sys.stdin = out, err, inp
    if isinstance(error, _GuardTimeout):
        status = "timeout"
    return status, value, error, _time.perf_counter() - t0


_GUARD_CODES.add(_call.__code__)  # exempt already while the embedded sources load


def _act_of(strategy, obs):
    """strategy.act(obs): inside the timed call, so a missing or broken `act` is caught too."""
    return strategy.act(obs)


def _describe(status, error, secs, limit):
    if status == "timeout":
        where = ""
        try:
            if error is not None:
                frames = _traceback.extract_tb(error.__traceback__)
                frames = [f for f in frames if f.name not in ("_on_alarm", "_call")][-3:]
                where = "\ninterrupted at:\n" + "".join(_traceback.format_list(frames))
        except BaseException:
            where = ""
        return "timeout: no result within %.2f s (limit %.2f s)%s" % (secs, limit, where[-1500:])
    if status == "bad":
        return "bad output: not a plain Python literal within the reply limit"
    try:
        return "".join(_traceback.format_exception(error))[-4000:]
    except BaseException:
        return "exception (traceback unavailable)"


def _load(src, cls_name, label):
    n = 0
    while "_hz_%s_%d" % (label, n) in _sys.modules:
        n += 1
    name = "_hz_%s_%d" % (label, n)
    filename = "<%s>" % name
    _linecache.cache[filename] = (len(src), None, src.splitlines(True), filename)
    module = _types.ModuleType(name)
    module.__file__ = filename
    module.TIME_BUDGET = _TIME_BUDGET
    module.print = _noop_print
    _sys.modules[name] = module
    try:
        exec(compile(src, filename, "exec"), module.__dict__)
        module.TIME_BUDGET = _TIME_BUDGET
        module.print = _noop_print
        return getattr(module, cls_name)
    except BaseException:
        _sys.modules.pop(name, None)
        raise


_LOAD_ERRORS = {}


def _load_all():
    t0 = _time.perf_counter()
    loaded = {"core": None, "fallback": None}
    parts = (
        ("fallback", _FALLBACK_SRC, _FALLBACK_CLASS, _FALLBACK_IMPORT_LIMIT_S),
        ("core", _CORE_SRC, _CORE_CLASS, None),
    )
    for label, src, cls_name, limit in parts:
        if src is None:
            continue
        left = _IMPORT_LIMIT_S - (_time.perf_counter() - t0)
        limit = min(limit, left) if limit is not None else left
        limit = max(limit, 0.5)
        status, value, error, secs = _call(_load, (src, cls_name, label), limit, False)
        if status == "ok":
            loaded[label] = value
        else:
            _LOAD_ERRORS[label] = _describe(status, error, secs, limit)
    return loaded["core"], loaded["fallback"]


try:
    _CORE_CLS, _FALLBACK_CLS = _load_all()
except BaseException:
    _CORE_CLS, _FALLBACK_CLS = None, None


class _HzGuard:
    def __init__(self, player_id):
        self.player_id = player_id
        self._core = None
        self._fallback = None
        self._stats = {
            "turns": 0,
            "core_ok": 0,
            "core_exceptions": 0,
            "core_timeouts": 0,
            "core_bad_output": 0,
            "fallback_used": 0,
            "fallback_failures": 0,
            "none_used": 0,
            "max_core_s": 0.0,
            "first_core_traceback": _LOAD_ERRORS.get("core"),
            "core_loaded": _CORE_CLS is not None,
            "fallback_loaded": _FALLBACK_CLS is not None,
            "core_init_error": None,
            "fallback_init_error": None,
            "fallback_load_error": _LOAD_ERRORS.get("fallback"),
            "first_fallback_error": None,
        }
        try:
            if _CORE_CLS is not None:
                lim = _CORE_INIT_LIMIT_S
                status, value, error, secs = _call(_CORE_CLS, (player_id,), lim, False)
                if status == "ok":
                    self._core = value
                else:
                    msg = _describe(status, error, secs, lim)
                    self._stats["core_init_error"] = msg
                    if self._stats["first_core_traceback"] is None:
                        self._stats["first_core_traceback"] = msg
            if _FALLBACK_CLS is not None:
                lim = _FALLBACK_INIT_LIMIT_S
                status, value, error, secs = _call(_FALLBACK_CLS, (player_id,), lim, False)
                if status == "ok":
                    self._fallback = value
                else:
                    self._stats["fallback_init_error"] = _describe(status, error, secs, lim)
        except BaseException:
            pass

    def act(self, obs):
        try:
            return self._act(obs)
        except BaseException:
            return None

    def _act(self, obs):
        t0 = _time.perf_counter()
        st = self._stats
        st["turns"] += 1
        core, fallback = self._core, self._fallback
        saved = None
        if core is not None:
            if fallback is not None:
                try:
                    saved = repr(obs)  # the core may mutate obs; the fallback gets a fresh copy
                except Exception:
                    saved = None
            limit = _ACT_LIMIT_S * _CORE_SHARE
            status, value, error, secs = _call(_act_of, (core, obs), limit, True)
            if secs > st["max_core_s"]:
                st["max_core_s"] = secs
            if status == "ok":
                st["core_ok"] += 1
                return value
            if status == "timeout":
                st["core_timeouts"] += 1
            elif status == "bad":
                st["core_bad_output"] += 1
            else:
                st["core_exceptions"] += 1
            if st["first_core_traceback"] is None:
                st["first_core_traceback"] = _describe(status, error, secs, limit)
            error = None
        if fallback is not None:
            fobs = obs
            if saved is not None:
                try:
                    fobs = _ast.literal_eval(saved)
                except Exception:
                    fobs = obs
            left = _ACT_LIMIT_S - (_time.perf_counter() - t0)
            if left >= _MIN_FALLBACK_S:
                status, value, error, secs = _call(_act_of, (fallback, fobs), left, True)
                if status == "ok":
                    st["fallback_used"] += 1
                    return value
                st["fallback_failures"] += 1
                if st["first_fallback_error"] is None:
                    st["first_fallback_error"] = _describe(status, error, secs, left)
        st["none_used"] += 1
        return None

    def guard_stats(self):
        """Counters of this instance: how often the core answered, failed, fell back."""
        try:
            return dict(self._stats)
        except BaseException:
            return {}


for _fn in (_call, _HzGuard.__init__, _HzGuard.act, _HzGuard._act, _HzGuard.guard_stats):
    _GUARD_CODES.add(_fn.__code__)
del _fn


class Strategy(_HzGuard):
    """Guarded strategy: never raises, never exceeds its time limit."""
